/**
 * Generates a 100% solvable non-deterministic 6x6 board by scrambling backwards from `solvedAnchorCars`
 * using reversible physical `computeSlideBounds` moves (`target.col <= 1`, `>= 2` Row-3 vertical blockers,
 * and `>= 1` cross-locked Row-3 vertical blocker so solving always takes `>= 4` moves).
 */
export function applyLiveNonDeterministicVariation(
  solvedAnchorCars,
  { walkSteps = 120, shuffleFleet = true } = {}
) {
  const twoPool = shuffleFleet
    ? cryptoShuffleCopy(TWO_CELL_BLOCKER_CLASSES)
    : TWO_CELL_BLOCKER_CLASSES;
  const threePool = shuffleFleet
    ? cryptoShuffleCopy(THREE_CELL_BLOCKER_CLASSES)
    : THREE_CELL_BLOCKER_CLASSES;
  const finishPool = shuffleFleet
    ? cryptoShuffleCopy(BLOCKER_FINISH_KEYS)
    : BLOCKER_FINISH_KEYS;

  const exitRow = GRID_SPEC.exitRow;

  for (let attempt = 0; attempt < 64; attempt++) {
    const cars = solvedAnchorCars.map((c) => ({ ...c }));

    let k2 = 0;
    let k3 = 0;
    let kFin = 0;
    for (let i = 0; i < cars.length; i++) {
      const c = cars[i];
      if (c.id === "target") continue;
      if (shuffleFleet) {
        c.vehicleClass =
          c.length === 3
            ? threePool[k3++ % threePool.length]
            : twoPool[k2++ % twoPool.length];
        c.finishKey = finishPool[kFin++ % finishPool.length];
      }
    }

    // 1. Pull hero GT Coupe West from solved E3–F3 to A3–B3 (col 0) or B3–C3 (col 1)
    const targetBounds0 = computeSlideBounds(cars, 0, GRID_SPEC.gridSize);
    if (targetBounds0) {
      const wantCol1 = walkSteps <= 85 && cryptoRandInt(2) === 1 && targetBounds0.maxCell >= 1;
      cars[0].col = wantCol1 ? Math.max(targetBounds0.minCell, 1) : targetBounds0.minCell;
    }

    // 2. Slide vertical vehicles east of target across Row 3 (exitRow = 2)
    for (let i = 1; i < cars.length; i++) {
      const c = cars[i];
      if (c.orientation !== "v" || c.col < cars[0].col + 2) continue;
      const b = computeSlideBounds(cars, i, GRID_SPEC.gridSize);
      if (!b) continue;
      const blockingCells = [];
      for (let cell = b.minCell; cell <= b.maxCell; cell++) {
        if (cell <= exitRow && cell + c.length - 1 >= exitRow) {
          blockingCells.push(cell);
        }
      }
      if (blockingCells.length > 0) {
        c.row = blockingCells[cryptoRandInt(blockingCells.length)];
      }
    }

    // 3. Deep reversible random walk across all vehicles
    let lastMovedIdx = -1;
    for (let step = 0; step < walkSteps; step++) {
      const inTail = step >= Math.floor(walkSteps * 0.62);
      const idx = cryptoRandInt(cars.length);
      if (idx === lastMovedIdx && cryptoRandInt(3) > 0) continue;

      const car = cars[idx];
      const b = computeSlideBounds(cars, idx, GRID_SPEC.gridSize);
      if (!b || b.minCell === b.maxCell) continue;

      const candidates = [];
      for (let cell = b.minCell; cell <= b.maxCell; cell++) {
        if (cell === b.currentCell) continue;
        if (idx === 0 && cell > (inTail ? 1 : 2)) continue;
        candidates.push(cell);
      }
      if (candidates.length === 0) continue;

      const nextCell = candidates[cryptoRandInt(candidates.length)];
      const prevCell = car.orientation === "h" ? car.col : car.row;
      if (car.orientation === "h") car.col = nextCell;
      else car.row = nextCell;

      if (inTail) {
        const blks = getRow3VerticalBlockerIndices(cars);
        if (cars[0].col > 1 || blks.length < 2) {
          if (car.orientation === "h") car.col = prevCell;
          else car.row = prevCell;
          continue;
        }
      }
      lastMovedIdx = idx;
    }

    // 4. Ensure target sits at col <= 1 and >= 2 Row-3 vertical blockers + >= 1 cross-lock
    if (cars[0].col > 1) {
      const tb = computeSlideBounds(cars, 0, GRID_SPEC.gridSize);
      if (tb && tb.minCell <= 1) {
        cars[0].col = tb.minCell;
      }
    }

    let blockers = getRow3VerticalBlockerIndices(cars);
    if (blockers.length < 2) {
      for (let i = 1; i < cars.length; i++) {
        const c = cars[i];
        if (c.orientation !== "v" || c.col < cars[0].col + 2) continue;
        const b = computeSlideBounds(cars, i, GRID_SPEC.gridSize);
        if (!b) continue;
        for (let cell = b.minCell; cell <= b.maxCell; cell++) {
          if (cell <= exitRow && cell + c.length - 1 >= exitRow) {
            c.row = cell;
            break;
          }
        }
      }
      blockers = getRow3VerticalBlockerIndices(cars);
    }

    if (!hasCrossLockedRow3Blocker(cars, blockers)) {
      for (let i = 1; i < cars.length; i++) {
        const c = cars[i];
        if (c.orientation !== "h") continue;
        const b = computeSlideBounds(cars, i, GRID_SPEC.gridSize);
        if (!b || b.minCell === b.maxCell) continue;
        for (let cell = b.minCell; cell <= b.maxCell; cell++) {
          if (cell === b.currentCell) continue;
          const prev = c.col;
          c.col = cell;
          const nextBlks = getRow3VerticalBlockerIndices(cars);
          if (nextBlks.length >= 2 && hasCrossLockedRow3Blocker(cars, nextBlks)) {
            break;
          }
          c.col = prev;
        }
        blockers = getRow3VerticalBlockerIndices(cars);
        if (blockers.length >= 2 && hasCrossLockedRow3Blocker(cars, blockers)) {
          break;
        }
      }
    }

    blockers = getRow3VerticalBlockerIndices(cars);
    if (
      cars[0].col <= 1 &&
      !isExitCorridorClear(cars) &&
      blockers.length >= 2 &&
      hasCrossLockedRow3Blocker(cars, blockers)
    ) {
      validateBoard(cars, GRID_SPEC.gridSize, GRID_SPEC.exitRow);
      return cars;
    }
  }

  // Deterministic 4-slide reversible fallback directly from solvedAnchorCars (still 100% solvable!)
  const fallback = solvedAnchorCars.map((c) => ({ ...c }));
  const tb = computeSlideBounds(fallback, 0, GRID_SPEC.gridSize);
  if (tb) fallback[0].col = tb.minCell;
  for (let i = 1; i < fallback.length; i++) {
    const c = fallback[i];
    if (c.orientation !== "v" || c.col < fallback[0].col + 2) continue;
    const b = computeSlideBounds(fallback, i, GRID_SPEC.gridSize);
    if (!b) continue;
    for (let cell = b.minCell; cell <= b.maxCell; cell++) {
      if (cell <= exitRow && cell + c.length - 1 >= exitRow) {
        c.row = cell;
        break;
      }
    }
  }
  for (let i = 1; i < fallback.length; i++) {
    const c = fallback[i];
    if (c.orientation !== "h") continue;
    const b = computeSlideBounds(fallback, i, GRID_SPEC.gridSize);
    if (!b) continue;
    for (let cell = b.maxCell; cell >= b.minCell; cell--) {
      const prev = c.col;
      c.col = cell;
      const blks = getRow3VerticalBlockerIndices(fallback);
      if (blks.length >= 2 && hasCrossLockedRow3Blocker(fallback, blks)) break;
      c.col = prev;
    }
    if (hasCrossLockedRow3Blocker(fallback, getRow3VerticalBlockerIndices(fallback))) break;
  }
  validateBoard(fallback, GRID_SPEC.gridSize, GRID_SPEC.exitRow);
  return fallback;
}

// Validate all 5 solved anchor templates at module load
for (let i = 0; i < SOLVED_ANCHOR_TEMPLATES.length; i++) {
  const tmpl = SOLVED_ANCHOR_TEMPLATES[i];
  validateBoard(tmpl.solvedCars, GRID_SPEC.gridSize, GRID_SPEC.exitRow);
  if (countBoardOverlaps(tmpl.solvedCars, GRID_SPEC.gridSize) !== 0) {
    throw new Error(`[Levels] Anchor template ${tmpl.id} has cell overlaps.`);
  }
  if (!isExitCorridorClear(tmpl.solvedCars, GRID_SPEC.gridSize, GRID_SPEC.exitRow)) {
    throw new Error(`[Levels] Anchor template ${tmpl.id} is not in a solved exit-clear pose.`);
  }
  const meta = LEVEL_META[i];
  if (meta && meta.vehicleCount !== tmpl.solvedCars.length) {
    throw new Error(
      `[Levels] LEVEL_META[${i}].vehicleCount (${meta.vehicleCount}) != anchor car count (${tmpl.solvedCars.length}).`
    );
  }
}

export const BASE_LEVELS = SOLVED_ANCHOR_TEMPLATES.map((tmpl) => ({
  id: tmpl.id,
  lap: tmpl.lap,
  stateKey: tmpl.stateKey,
  title: tmpl.title,
  cars: applyLiveNonDeterministicVariation(tmpl.solvedCars, {
    walkSteps: tmpl.walkSteps,
    shuffleFleet: false,
  }),
}));

export const LEVELS = BASE_LEVELS;

export function cloneLapConfig(lapCfg) {
  return {
    id: lapCfg.id,
    lap: lapCfg.lap || lapCfg.id,
    stateKey: lapCfg.stateKey,
    title: lapCfg.title,
    vehicleCount: lapCfg.cars.length,
    cars: lapCfg.cars.map((c) => ({ ...c })),
  };
}

/**
 * Generates a fresh 5-lap non-deterministic 100%-solvable `6x6` race pack (`Lap 1`..`Lap 5`).
 * Both Human and AI boards clone from the exact same `pack[lap - 1]` so every lap is 100% fair!
 */
export function generateRacePack() {
  const pack = [];
  for (let i = 0; i < TOTAL_LAPS; i++) {
    const tmpl = SOLVED_ANCHOR_TEMPLATES[i % SOLVED_ANCHOR_TEMPLATES.length];
    const cars = applyLiveNonDeterministicVariation(tmpl.solvedCars, {
      walkSteps: tmpl.walkSteps,
      shuffleFleet: true,
    });
    pack.push({
      id: tmpl.id,
      lap: i + 1,
      stateKey: tmpl.stateKey,
      title: tmpl.title,
      vehicleCount: cars.length,
      cars,
    });
  }
  return pack;
}

export function getLevelConfig(levelNumber) {
  const idx = Math.max(
    0,
    Math.min(SOLVED_ANCHOR_TEMPLATES.length - 1, (Number(levelNumber) || 1) - 1)
  );
  const tmpl = SOLVED_ANCHOR_TEMPLATES[idx];
  const cars = applyLiveNonDeterministicVariation(tmpl.solvedCars, {
    walkSteps: tmpl.walkSteps,
    shuffleFleet: true,
  });
  return {
    id: tmpl.id,
    lap: idx + 1,
    stateKey: tmpl.stateKey,
    title: tmpl.title,
    vehicleCount: cars.length,
    cars,
  };
}

export function generateProceduralScramble() {
  const idx = cryptoRandInt(SOLVED_ANCHOR_TEMPLATES.length);
  const tmpl = SOLVED_ANCHOR_TEMPLATES[idx];
  const cars = applyLiveNonDeterministicVariation(tmpl.solvedCars, {
    walkSteps: tmpl.walkSteps + 40,
    shuffleFleet: true,
  });
  return {
    id: tmpl.id,
    lap: idx + 1,
    stateKey: "scramble",
    title: `${tmpl.title} · Scramble`,
    vehicleCount: cars.length,
    cars,
  };
}
